        return (gap / 2) + (gap % 2);
    }

    public static void merge(int[] arr1, int[] arr2, int n, int m) {
        int gap = n + m;
        gap = nextGap(gap);
        while (gap > 0) {
            int i = 0;
            // comparing elements in the first array
            while (i + gap < n) {
                if (arr1[i] > arr1[i + gap]) {
                    int temp = arr1[i];
                    arr1[i] = arr1[i + gap];
                    arr1[i + gap] = temp;
                }
                i++;
            }

            // comparing elements in both arrays
            int j = gap > n ? gap - n : 0;
            while (i < n && j < m) {
                if (arr1[i] > arr2[j]) {
                    int temp = arr1[i];
                    arr1[i] = arr2[j];
                    arr2[j] = temp;
                }
                i++;
                j++;
            }

            if (j < m) {
                // comparing elements in the second array
                j = 0;
                while (j + gap < m) {
                    if (arr2[j] > arr2[j + gap]) {
                        int temp = arr2[j];
                        arr2[j] = arr2[j + gap];
                        arr2[j + gap] = temp;
                    }
